mapper.select:
select to_char(ROWNUM) as "순번", a.site_nm as "동", a.site_cd as "동 코드", a.site_nm_path as "소속", a.site_nm2 as "구", a.site_nm3 as "사업소", case a.use_cd when '1' then '검침중' when '7' then '검침중지' end "검침 상태", a.admin_id as "수용가번호", a.cs_no as "CS 번호", a.cust_nm as "수용가 이름", a.addr_old as "구주소", a.addr_new as "도로명주소", a.meter_no as "계량기번호", a.use_type as "업종", to_char(a.pipe_dia) as "관경", a.blk_nm1 as "하위 블럭", a.blk_nm2 as "상위 블럭", a.read_opr as "검침원", a.check_day as "검침일", a.cust_phone as "전화번호", a.ctchar_nm as "정수장", to_char(a.instl_day, 'yyyy-mm-dd hh24:mi') as "설치일", a.tap_status_cd_nm as "상태2", a.apthouse_cd_nm as "계량기", to_char(b.meas_dt, 'yyyy-mm-dd hh24:mi') as "측정날짜", case instr(b.stat_cd, '1') when 1 then '통신 장애' when 2 then '계량기 장애' when 3 then 'Q3 초과' when 4 then '역류' when 5 then '누수' when 8 then 'BAT' else '정상' end "계량기 상태", a.ami_type as "단말 타입", a.dev_no as "단말 번호", a.company_nm as "단말 회사", b.accu_iv as "검침값", to_char(b.raw_cnt_0d) as "금일 수신 개수", to_char(b.term_cv_0d) as "금일 사용량", to_char(b.raw_cnt_1d) as "어제 수신 개수", to_char(b.term_cv_1d) as "어제 사용량", to_char(b.raw_cnt_7d) as "최근 7일 수신 개수", to_char(b.term_cv_7d) as "최근 7일 사용량", to_char(b.raw_cnt_30d) as "최근 30일 수신 개수", to_char(b.term_cv_30d) as "최근 30일 사용량", to_char(b.delay_rcv) as "딜레이" from vi_m1_sv_point_List a left outer join vi_m1_sv_meas_now b on b.point_sq = a.point_sq
a.site_sq in (
select a.site_sq from (
select a.* from vi_m1_sv_site_list a start with up_site_sq = #{upSiteSq} connect by prior site_sq = up_site_sq order siblings by up_site_sq asc
) a where a.lv = 3
)
and a.site_sq = #{siteSq}
AND a.use_cd = #{useCd}
AND instr(b.stat_cd, '1') = to_number(#{statCd})
and a.company_sq = #{comSq}
and a.company_sq IS NULL
and a.ami_type = #{amiType}
and a.ami_type IS NULL
and a.use_type = #{useType}
and a.use_type IS NULL
and a.ctchar_nm = #{ctcharNm}
and a.ctchar_nm IS NULL
and a.point_sq = #{pointSq}
and a.blk_sq = #{blkSq}
and a.blk_sq IS NULL
AND to_char(extract( year from a.instl_day)) = to_char(#{instlDay})
and a.instl_day is null
and a.pipe_dia = to_number(#{pipeDia})
and a.pipe_dia is null
and ( a.cust_nm like '%${searchParam}%' or a.admin_id like '%${searchParam}%' or a.cs_no like '%${searchParam}%' or a.addr_new like '%${searchParam}%'
)
and a.dev_no like '%${searchParam}%'
